deeper_reasoning_2:
\noindent\textbf{Claim.} The two $n_{12}=1$ semiclassical descriptions are selected in opposite size hierarchies, but their coexistence as finite-volume quantum-mechanical endpoints does not imply a distinct confining phase transition. For $L_1=L_2=L_T$,
\[
\frac{\Delta E^{\rm cl}_{\rm non\text{-}flat}}{\Delta E^{1\text{-}{\rm loop}}_{\rm flat}}
\propto \frac{L_3^4}{N\lambda L_T^4}.
\]
Thus the non-flat monopole background is preferred when $L_T^4\gg L_3^4/(N\lambda)$, while the flat vortex background is preferred when $L_T^4\ll L_3^4/(N\lambda)$. Since the interpolation is a finite-dimensional quantum mechanics, a continuous path may reorder levels between these endpoints while the common branch function from the cyclic normal form remains the same after relabelling.

\noindent\textbf{Premises.}
\[
\begin{aligned}
\mathrm{(P1)}&\quad N\geq2,
\quad L_3,L_T,\lambda>0,
\quad L_1=L_2=L_T.\\
\mathrm{(P2)}&\quad R(L_T):=\frac{\Delta E^{\rm cl}_{\rm non\text{-}flat}}{\Delta E^{1\text{-}{\rm loop}}_{\rm flat}}
=c\frac{L_3^4}{N\lambda L_T^4}\quad \text{for some constant }c>0.\\
\mathrm{(P3)}&\quad R(L_T)\ll1\text{ selects the non-flat realization, and }R(L_T)\gg1\text{ selects the flat realization.}\\
\mathrm{(P4)}&\quad \mathcal H\cong\mathbb C^N\text{ is the retained quantum-mechanical low-energy space in the crossover region.}\\
\mathrm{(P5)}&\quad H(t)\text{ is a finite Hermitian }N\times N\text{ matrix depending continuously on }t\in[0,1].\\
\mathrm{(P6)}&\quad \text{A thermodynamic phase transition requires a nonanalyticity in a thermodynamic potential.}\\
\mathrm{(P7)}&\quad \text{The endpoint spectra share the theta-dependent function proved in the cyclic normal form.}
\end{aligned}
\]

\noindent\textbf{Derivation.}
By (P2),
\begin{align}
R(L_T)
&=c\frac{L_3^4}{N\lambda L_T^4}. && \text{definition of the comparison ratio}
\end{align}
If $L_T^4\gg L_3^4/(N\lambda)$, then
\begin{align}
\frac{L_3^4}{N\lambda L_T^4}&\ll1,\\
R(L_T)&\ll1,\\
\Delta E^{\rm cl}_{\rm non\text{-}flat}&\ll \Delta E^{1\text{-}{\rm loop}}_{\rm flat},\\
\text{so the non-flat realization is selected} && \text{by (P3)}.
\end{align}
If $L_T^4\ll L_3^4/(N\lambda)$, then
\begin{align}
\frac{L_3^4}{N\lambda L_T^4}&\gg1,\\
R(L_T)&\gg1,\\
\Delta E^{1\text{-}{\rm loop}}_{\rm flat}&\ll \Delta E^{\rm cl}_{\rm non\text{-}flat},\\
\text{so the flat realization is selected} && \text{by (P3)}.
\end{align}
For the interpolation, fix inverse temperature $\beta>0$ and define
\begin{align}
Z_\beta(t)&:=\operatorname{tr}_{\mathcal H}\left(e^{-\beta H(t)}\right). && \text{finite-volume partition function}
\end{align}
Because the matrix exponential and trace are continuous functions of the matrix entries,
\begin{align}
H(t)\text{ continuous }&\Longrightarrow Z_\beta(t)\text{ continuous and positive}. && \text{by (P4)--(P5)}
\end{align}
If the entries of $H(t)$ are analytic, the same finite matrix expression is analytic in $t$. Hence any level crossing or reordering along the path is a finite-volume spectral rearrangement, not by itself a thermodynamic singularity. Combining this with (P7), the two endpoint descriptions may exchange which semiclassical variables are economical while retaining the same theta-dependent electric-flux branch function.

\noindent\textbf{Final Result.}
\[
\boxed{L_T^4\gg \frac{L_3^4}{N\lambda}:\text{ non-flat monopole description},
\qquad
L_T^4\ll \frac{L_3^4}{N\lambda}:\text{ flat vortex description},
\qquad
\text{finite-volume interpolation permits crossover or level reordering.}}
\]
\hfill$\blacksquare$

deeper_reasoning_3:
\noindent\textbf{Claim.} In the $n_{23}=1$ two-stage compactification, the twisted dual-photon boundary condition produces a classical mass gap, locks the infrared field to the $N$ Weyl-vector vacua, and turns each monopole operator into the center-vortex deformation of the two-dimensional $Z_N$ topological theory. In the regime $\ell_D\gg L_2\gg L_3$,
\[
S_{\rm IR}=\frac{iN}{2\pi}\int \phi\,da-2\zeta_v\int d^2x\cos\left(\phi+\frac{\theta}{N}\right),
\qquad \zeta_v=NL_2\zeta_m,
\]
with
\[
\varepsilon_k(\theta)=-2\zeta_v\cos\left(\frac{2\pi k+\theta}{N}\right),
\qquad k=0,\ldots,N-1.
\]

\noindent\textbf{Premises.}
\[
\begin{aligned}
\mathrm{(P1)}&\quad N\geq2,
\quad p\in\{1,\ldots,N-1\},
\quad k_2\in\mathbb Z,
\quad \ell_D\gg L_2\gg L_3.\\
\mathrm{(P2)}&\quad \widetilde\sigma_p(x_2+L_2)=e^{2\pi ip/N}\widetilde\sigma_p(x_2).\\
\mathrm{(P3)}&\quad -\partial_2^2 e^{iqx_2}=q^2e^{iqx_2},\text{ and }q^2\text{ is the two-dimensional mass squared.}\\
\mathrm{(P4)}&\quad \min_{k\in\mathbb Z}|k+p/N|=1/N\text{ for the lightest twisted sector}.\\
\mathrm{(P5)}&\quad \sigma_k^*=\frac{2\pi k}{N}\rho,
\quad e^{i\alpha_a\cdot\sigma_k^*}=e^{2\pi ik/N}\text{ for }a=1,\ldots,N.\\
\mathrm{(P6)}&\quad \mathcal M_a(\sigma):=\zeta_m e^{i\alpha_a\cdot\sigma+i\theta/N}\text{ is a monopole insertion before the final reduction.}\\
\mathrm{(P7)}&\quad \sigma=\rho\phi\text{ in the deep infrared, and the }a\text{-sum gives }\zeta_v:=NL_2\zeta_m.\\
\mathrm{(P8)}&\quad \int Da\,\exp\left(-\frac{iN}{2\pi}\int\phi\,da\right)\text{ imposes }e^{iN\phi}=1.
\end{aligned}
\]

\noindent\textbf{Derivation.}
Let one twisted mode have $x_2$ dependence $e^{iqx_2}$. Then
\begin{align}
e^{iq(x_2+L_2)}&=e^{2\pi ip/N}e^{iqx_2} && \text{by (P2)},\\
e^{iqL_2}&=e^{2\pi ip/N} && \text{cancel }e^{iqx_2},\\
qL_2&=2\pi\left(k_2+\frac{p}{N}\right) && \text{equality of phases modulo }2\pi,\\
q&=\frac{2\pi}{L_2}\left(k_2+\frac{p}{N}\right). && \text{divide by }L_2
\end{align}
Therefore
\begin{align}
M^2_{p,k_2}&=q^2 && \text{by (P3)},\\
&=\left(\frac{2\pi}{L_2}\right)^2\left(k_2+\frac{p}{N}\right)^2,\\
M_{\rm min}&=\frac{2\pi}{NL_2} && \text{by (P4)}.
\end{align}
Thus nonzero twisted dual-photon fluctuations are massive at the scale $2\pi/(NL_2)$, so the long-distance field is locked to the discrete vacua in (P5). Evaluate a monopole insertion on such a vacuum:
\begin{align}
L_2\mathcal M_a(\sigma_k^*)
&=L_2\zeta_m e^{i\alpha_a\cdot\sigma_k^*+i\theta/N} && \text{by (P6)},\\
&=L_2\zeta_m e^{i(2\pi k+\theta)/N} && \text{by (P5)}.
\end{align}
This is independent of the root label $a$ except for the common multiplicity of $N$ insertions. Hence the summed deformation is
\begin{align}
\sum_{a=1}^N L_2\mathcal M_a(\sigma_k^*)+\text{c.c.}
&=2NL_2\zeta_m\cos\left(\frac{2\pi k+\theta}{N}\right) && \text{add complex conjugates},\\
&=2\zeta_v\cos\left(\frac{2\pi k+\theta}{N}\right) && \text{by (P7)}.
\end{align}
Replacing the discrete label by $\sigma=\rho\phi$ gives the infrared deformation
\begin{align}
S_{\rm IR}&=\frac{iN}{2\pi}\int \phi\,da-2\zeta_v\int d^2x\cos\left(\phi+\frac{\theta}{N}\right). && \text{by (P7)}
\end{align}
Finally, (P8) imposes $e^{iN\phi}=1$, so
\begin{align}
\phi&=\frac{2\pi k}{N}\pmod{2\pi},\quad k=0,\ldots,N-1,\\
\varepsilon_k(\theta)&=-2\zeta_v\cos\left(\frac{2\pi k+\theta}{N}\right). && \text{read from the area density}
\end{align}

\noindent\textbf{Final Result.}
\[
\boxed{M_{\rm min}=\frac{2\pi}{NL_2},
\quad L_2\zeta_m e^{i\alpha_a\cdot\sigma_k^*+i\theta/N}=L_2\zeta_m e^{i(2\pi k+\theta)/N},
\quad S_{\rm IR}=\frac{iN}{2\pi}\int\phi\,da-2\zeta_v\int d^2x\cos\left(\phi+\frac{\theta}{N}\right).}
\]
\hfill$\blacksquare$

deeper_reasoning_4:
\noindent\textbf{Claim.} The infrared object produced by the $n_{23}=1$ reduction has the two defining operational diagnostics of a center vortex: a short-ranged interaction and a fundamental Wilson-loop phase depending only on whether the fractionalized flux pierces the loop. More precisely,
\[
r_v=\frac{NL_2}{2\pi},
\qquad
W(C)=\exp\left(-\frac{2\pi i}{N}\Theta_D(x)\right),
\qquad C=\partial D.
\]
Together with the deformed $Z_N$ branch densities, the charge-$q$ loop obeys
\[
\langle W_q(C)\rangle\sim \exp[-(\varepsilon_q(\theta)-\varepsilon_0(\theta))A_D].
\]

\noindent\textbf{Premises.}
\[
\begin{aligned}
\mathrm{(P1)}&\quad \omega:=\frac{2\pi}{NL_2},
\quad A_{ij}:=L_3\left(\frac{2\pi}{g}\right)^2\alpha_i\cdot\alpha_j.\\
\mathrm{(P2)}&\quad V_{ij}(x)=\frac{A_{ij}}{L_2}\frac{1}{2\pi}K_0(\omega |x|).\\
\mathrm{(P3)}&\quad K_0(y)\sim \left(\frac{\pi}{2y}\right)^{1/2}e^{-y}\quad (y\to\infty).\\
\mathrm{(P4)}&\quad W(C)=\frac{1}{N}\sum_{j=1}^{N}\exp\left(i\int_D\nu_j\cdot f\right).\\
\mathrm{(P5)}&\quad \nu_i\cdot\nu_j=\delta_{ij}-\frac{1}{N}.\\
\mathrm{(P6)}&\quad f=2\pi\nu_i\Theta_D(x),\text{ where }\Theta_D(x)=1\text{ if }x\in D\text{ and }0\text{ otherwise.}\\
\mathrm{(P7)}&\quad \varepsilon_k(\theta)=-2\zeta_v\cos\left(\frac{2\pi k+\theta}{N}\right).\\
\mathrm{(P8)}&\quad \text{A charge-}q\text{ loop places branch }q\text{ inside }D\text{ and the vacuum branch outside }D.
\end{aligned}
\]

\noindent\textbf{Derivation.}
For $\omega |x|\to\infty$,
\begin{align}
V_{ij}(x)
&=\frac{A_{ij}}{L_2}\frac{1}{2\pi}K_0(\omega |x|) && \text{by (P2)},\\
&\sim \frac{A_{ij}}{L_2}\frac{1}{2\pi}\left(\frac{\pi}{2\omega |x|}\right)^{1/2}e^{-\omega |x|} && \text{by (P3)},\\
&=\frac{A_{ij}}{L_2}\frac{1}{4\pi}\left(\frac{NL_2}{|x|}\right)^{1/2}e^{-2\pi |x|/(NL_2)} && \text{use (P1)}.
\end{align}
The exponential decay length is therefore
\begin{align}
r_v&=\omega^{-1}=\frac{NL_2}{2\pi}. && \text{by (P1)}
\end{align}
For the Wilson loop,
\begin{align}
\int_D\nu_j\cdot f
&=2\pi\left(\delta_{ij}-\frac{1}{N}\right)\Theta_D(x) && \text{by (P5)--(P6)},\\
W(C)&=\frac{1}{N}\sum_{j=1}^{N}\exp\left(2\pi i\left(\delta_{ij}-\frac{1}{N}\right)\Theta_D(x)\right) && \text{by (P4)}.
\end{align}
If $\Theta_D(x)=0$, every summand is $1$, so $W(C)=1$. If $\Theta_D(x)=1$, then
\begin{align}
W(C)
&=\frac{1}{N}\left(e^{2\pi i(1-1/N)}+(N-1)e^{-2\pi i/N}\right),\\
&=\frac{1}{N}\left(e^{-2\pi i/N}+(N-1)e^{-2\pi i/N}\right) && \text{since }e^{2\pi i}=1,\\
&=e^{-2\pi i/N}.
\end{align}
Both cases are summarized as
\begin{align}
W(C)&=\exp\left(-\frac{2\pi i}{N}\Theta_D(x)\right). && \text{combine the two values}
\end{align}
For a charge-$q$ loop, (P8) gives
\begin{align}
Z_q(C;\theta)&\sim e^{-\varepsilon_q(\theta)A_D}e^{-\varepsilon_0(\theta)(A_M-A_D)},\\
Z_0(\theta)&\sim e^{-\varepsilon_0(\theta)A_M},\\
\langle W_q(C)\rangle&=\frac{Z_q(C;\theta)}{Z_0(\theta)}
\sim e^{-(\varepsilon_q(\theta)-\varepsilon_0(\theta))A_D}. && \text{cancel outside-vacuum area}
\end{align}

\noindent\textbf{Final Result.}
\[
\boxed{V_{ij}(x)\sim \frac{A_{ij}}{L_2}\frac{1}{4\pi}\left(\frac{NL_2}{|x|}\right)^{1/2}e^{-2\pi |x|/(NL_2)},
\quad r_v=\frac{NL_2}{2\pi},
\quad W(C)=e^{-2\pi i\Theta_D(x)/N},
\quad \langle W_q(C)\rangle\sim e^{-(\varepsilon_q-\varepsilon_0)A_D}.}
\]
\hfill$\blacksquare$

deeper_reasoning_5:
\noindent\textbf{Claim.} The preceding bridge results jointly satisfy the paper-level target: the two quantum-mechanical hierarchies realize the same deformed $Z_N$ infrared theory, and the two-dimensional monopole EFT reduces to a center-vortex $Z_N$ TQFT with fractional Wilson-loop response. Define
