\text{ and }W(C)=e^{-2\pi i\Theta_D(x)/N}.\\
\mathrm{(P3)}&\quad \text{The cyclic Hamiltonian bridge proves all spectral and basis clauses in (P1).}\\
\mathrm{(P4)}&\quad \text{The energy-selection and finite-volume argument proves the crossover clause in (P1).}\\
\mathrm{(P5)}&\quad \text{The twisted reduction proves the locking, }S_{\rm IR},\text{ and monopole-to-vortex clauses in (P2).}\\
\mathrm{(P6)}&\quad \text{The vortex-diagnostic argument proves the short-range interaction, Wilson phase, and area-law clauses in (P2).}\\
\mathrm{(P7)}&\quad \text{The robustness domain is restricted to }\min(L_3,L_T)\ll\Lambda^{-1}\text{ for }n_{12}=1\
&\quad \text{and to }\ell_D\gg L_2\gg L_3\text{ after }\Lambda NL_3\ll1\text{ for }n_{23}=1.
\end{aligned}
